            document.getElementById('world-location').innerText = SafeGetValue(characterData, '世界.地点', 'user的家');

            updateProgressBar('linxiaoqing-affection-bar', 'linxiaoqing-affection', null, SafeGetValue(characterData, '林晓晴.与user的好感度'), 0, 400, 'var(--accent-highlight-xiaoqing)');
            updateProgressBar('suwanyi-affection-bar', 'suwanyi-affection', null, SafeGetValue(characterData, '苏婉仪.与user的好感度'), 0, 400, 'var(--accent-highlight-wanyi)');
            updateProgressBar('chuyue-affection-bar', 'chuyue-affection', null, SafeGetValue(characterData, '楚月.与user的好感度'), 0, 400, 'var(--accent-highlight-chuyue)');

        } catch (error) {
            document.getElementById('status-card').innerHTML = `<p style='color:red; padding:10px;'>状态栏加载出错: ${error.message}</p>`;
        }
    }

    function toggleSection(element) {
